// Process business alerts
const input = $input.first().json;
const alerts = input.alerts || [];
const summary = input.summary || { total: 0, critical: 0, high: 0, medium: 0, low: 0 };

// Separate by severity
const criticalAlerts = alerts.filter(a => a.severity === 'critical');
const highAlerts = alerts.filter(a => a.severity === 'high');
const mediumAlerts = alerts.filter(a => a.severity === 'medium');

// Format alert messages for Slack
const formatAlert = (alert) => {
  const valueFmt = typeof alert.current_value === 'number' 
    ? (alert.current_value > 1000 ? '$' + (alert.current_value / 1000).toFixed(1) + 'K' : alert.current_value.toFixed(2))
    : alert.current_value;
  const targetFmt = alert.target_value 
    ? (alert.target_value > 1000 ? '$' + (alert.target_value / 1000).toFixed(1) + 'K' : alert.target_value.toFixed(2))
    : 'N/A';
  return `• *${alert.kpi_name}*: ${valueFmt} (target: ${targetFmt})\n  _${alert.message}_`;
};

const criticalMessages = criticalAlerts.map(formatAlert).join('\n');
const highMessages = highAlerts.map(formatAlert).join('\n');

return [{
  json: {
    hasAlerts: alerts.length > 0,
    hasCritical: criticalAlerts.length > 0,
    hasHigh: highAlerts.length > 0,
    summary,
    criticalAlerts,
    highAlerts,
    mediumAlerts,
    criticalMessages: criticalMessages || 'None',
    highMessages: highMessages || 'None',
    allAlerts: alerts,
    timestamp: new Date().toISOString(),
    kpisChecked: input.kpis_checked,
    rulesEvaluated: input.rules_evaluated
  }
}];

